"""Original workspace CSS, shared unchanged by trusted entry points."""
import streamlit as st

WORKSPACE_CSS="<style>\n    .stApp { background:#080d16; color:#e7edf7; }\n    .stApp, .stApp p, .stApp li, .stApp label, .stApp [data-testid='stMarkdownContainer'] { color:#dbe5f2; }\n    [data-testid='stSidebar'] { background:#0c1421; width:230px !important; min-width:230px !important; }\n    [data-testid='stWidgetLabel'], [data-testid='stMetricLabel'] { color:#c3d0e0 !important; }\n    .stCaption, [data-testid='stCaptionContainer'] { color:#aebed1 !important; }\n    h1, h2, h3 { color:#f1f5fb !important; }\n    input, textarea { background:#111b2b !important; color:#e7edf7 !important; border-color:#38516e !important; }\n    [data-baseweb='select'] > div { background:#111b2b !important; border-color:#38516e !important; }\n    [data-baseweb='popover'], [data-baseweb='menu'] { background:#111b2b !important; }\n    [data-baseweb='menu'] * { color:#e7edf7 !important; }\n    [data-testid='stSidebar'] [data-testid='stMarkdownContainer'], [data-testid='stSidebar'] label { color:#c7d4e4 !important; }\n    .block-container { padding-top:0.65rem; padding-left:1.3rem; padding-right:1.3rem; max-width:1550px; }\n    div[data-testid='stMetric'] { background:#111b2b; border:1px solid #20334d; padding:14px; border-radius:10px; }\n    div[data-testid='stDataFrame'] { border:1px solid #20334d; border-radius:8px; }\n    div[data-testid='stPlotlyChart'] { background:#0d1522; border:1px solid #20334d; border-radius:10px; padding:4px; }\n    [data-testid='stSidebar'] [role='radiogroup'] label { padding:3px 6px; border-radius:6px; }\n    [data-testid='stSidebar'] [role='radiogroup'] label:hover { background:#14263a; }\n    div[data-testid='stVerticalBlock'] > div:has(> div[data-testid='stMetric']) { gap:0.5rem; }\n    div[data-baseweb='input'] > div, div[data-baseweb='select'] > div { background:#0e1928; border-color:#28415d; }\n    @media (max-width: 1100px) {\n      .block-container { padding-left:1rem; padding-right:1rem; }\n      [data-testid='stSidebar'] { min-width:220px; max-width:240px; }\n    }\n    @media (min-width: 1600px) {\n      .block-container { max-width: 1500px; }\n    }\n    </style>"


def render_workspace_styles():
    st.html(WORKSPACE_CSS)
